        "code": "interface RemoteContainer {\n  name: string;\n  url: string;\n  version: string;\n  exposedModules: Map<string, () => any>;\n}\n\nclass ModuleFederationHost {\n  private remotes = new Map<string, RemoteContainer>();\n\n  registerRemote(name: string, url: string, version: string): void {\n    this.remotes.set(name, {\n      name,\n      url,\n      version,\n      exposedModules: new Map(),\n    });\n  }\n\n  exposeRemoteModule(remoteName: string, moduleKey: string, factory: () => any): void {\n    const remote = this.remotes.get(remoteName);\n    if (!remote) throw new Error(`Remote ${remoteName} not registered`);\n    remote.exposedModules.set(moduleKey, factory);\n  }\n\n  loadRemote<T = any>(remoteName: string, moduleKey: string): T {\n    const remote = this.remotes.get(remoteName);\n    if (!remote) throw new Error(`Remote ${remoteName} unavailable`);\n    const factory = remote.exposedModules.get(moduleKey);\n    if (!factory) throw new Error(`Module ${moduleKey} not found in ${remoteName}`);\n    return factory();\n  }\n}\n\nconst host = new ModuleFederationHost();\nhost.registerRemote(\"billingApp\", \"https://cdn.enterprise.io/billing/remoteEntry.js\", \"2.4.0\");\nhost.exposeRemoteModule(\"billingApp\", \"./InvoiceCalculator\", () => ({\n  calculateTax: (subtotal: number, rate: number) => subtotal * rate,\n  formatCurrency: (amount: number) => `$${amount.toFixed(2)}`,\n}));\n\nconst billingModule = host.loadRemote(\"billingApp\", \"./InvoiceCalculator\");\nconst tax = billingModule.calculateTax(500, 0.08);\nconsole.log(`[Host Federation] Remote Loaded: billingApp v2.4.0`);\nconsole.log(`[Host Federation] Calculated Tax: ${billingModule.formatCurrency(tax)}`);\n",
        "example": "An international airport terminal with independent airline check-in desks and duty-free storefronts operating autonomously without airport-wide rebuilding.",
