        "code": "interface CRDTPNState {\n  p: Record<string, number>;\n  n: Record<string, number>;\n}\n\nclass PNCounterCRDT {\n  constructor(public id: string, public state: CRDTPNState = { p: {}, n: {} }) {}\n\n  inc(val = 1) { this.state.p[this.id] = (this.state.p[this.id] || 0) + val; }\n  dec(val = 1) { this.state.n[this.id] = (this.state.n[this.id] || 0) + val; }\n\n  value(): number {\n    const sumP = Object.values(this.state.p).reduce((a, b) => a + b, 0);\n    const sumN = Object.values(this.state.n).reduce((a, b) => a + b, 0);\n    return sumP - sumN;\n  }\n\n  merge(peer: PNCounterCRDT) {\n    for (const [k, v] of Object.entries(peer.state.p)) {\n      this.state.p[k] = Math.max(this.state.p[k] || 0, v);\n    }\n    for (const [k, v] of Object.entries(peer.state.n)) {\n      this.state.n[k] = Math.max(this.state.n[k] || 0, v);\n    }\n  }\n}\n\nconst nodeEast = new PNCounterCRDT(\"us-east\");\nconst nodeWest = new PNCounterCRDT(\"us-west\");\n\nnodeEast.inc(10);\nnodeWest.inc(15);\nnodeEast.dec(2);\n\nnodeEast.merge(nodeWest);\nnodeWest.merge(nodeEast);\n\nconsole.log(`[CRDT Mesh] East Value: ${nodeEast.value()}`);\nconsole.log(`[CRDT Mesh] West Value: ${nodeWest.value()}`);\nconsole.log(`[CRDT Mesh] Converged: ${nodeEast.value() === nodeWest.value()}`);\n",
